#include <cmath>
namespace speed {
const DracoBodyDefinition &DracoBody::rule(const RunRuntime &r,const BossBodyState &b) {const auto boss=r.content->boss_bodies[b.definition-1].boss;return *std::find_if(r.content->draco_bodies.begin(),r.content->draco_bodies.end(),[&](const auto &p){return p.boss==boss;});}
EnemyHandle DracoBody::spawn(RunRuntime &r,uint32_t definition,godot::Vector2 at,bool entrance) {
    if (!definition || definition>r.content->boss_bodies.size() || r.content->bosses[r.content->boss_bodies[definition-1].boss-1].kind!=4) return {};
    const auto actor=PhaseController::spawn(r,definition,at,false);auto *b=PhaseController::find(r,actor);if (!b) return {};const auto &p=rule(r,*b);b->draco.width=p.body_width;b->draco.head_scale=p.head_scale;
    for (uint32_t j=0;j<p.body_segments;++j) {EnemySpawn options;options.position=at;options.is_boss=true;options.origin=SpawnOrigin::BossPart;const auto id=EnemySystem::spawn_base(r,r.content->boss_bodies[definition-1].enemy-1,options);if (id<0) {PhaseController::cancel(r,actor);return {};}const auto part=r.state.enemy_handles.at(r.state.rows_by_id.at(id));auto &e=r.state.enemies[part.slot];e.parent=actor;e.parent_id=r.state.enemy_handles.entity_id(actor);e.damage_target=actor;e.hp=e.max_hp=p.part_hp;e.armor=p.part_armor;e.role=SpawnRole::BossPart;r.state.enemies[actor.slot].parts.push_back(part);b->participants.push_back({part,actor,id,false,true});}
    update(r,*b);return actor;
}
void DracoBody::step(RunRuntime &r,BossBodyState &b,double dt) {auto &e=r.state.enemies[b.actor.slot];const auto &p=rule(r,b);if (r.state.control.lab_mode) {e.vel={};update(r,b);return;}const TrackingPolicy tracking{r.state.draw.tracing,e.held,r.state.enemy_handles.contains(e.pump_owner)};const auto delta=tracking.target(e.pos,e.facing,r.state.ship_pos)-e.pos;e.vel={};if (delta.length()>p.approach_distance) {const auto from=e.pos;e.pos+=delta.normalized()*r.content->bosses[p.boss-1].speed*dt;e.facing=tracking.angle(e.facing,delta.angle());e.vel=(e.pos-from)/dt;}update(r,b);}
void DracoBody::update(RunRuntime &r,BossBodyState &b) {DracoPose::update(r,b);}
void DracoBody::cancel(RunRuntime &r,BossBodyState &b) {DracoPicaro::clear(r,b);DracoPose::reset(r,b);for (auto &p:b.participants) {p.active=false;if (!p.is_body) EnemySystem::mark_dead(r,p.actor);}b.draco.override_points.clear();r.state.encounter_protected=false;}
void DracoBody::damaged(RunRuntime &r,BossBodyState &b) {
    auto &e=r.state.enemies[b.actor.slot];const auto &p=rule(r,b);if (b.phase<=2 && e.hp<=e.max_hp*(b.phase==1?p.threshold_1:p.threshold_2)) {e.hp=e.max_hp*(b.phase==1?p.threshold_1:p.threshold_2);for (uint32_t row=0;row<r.state.bosses.techniques.size();++row) if (same_handle(r.state.bosses.techniques[row].actor,b.actor)) TechniqueRunner::cancel(r,r.state.bosses.handles.at(row));for (auto &f:r.state.bosses.flows) if (same_handle(f.actor,b.actor)) FlowRunner::cancel(r,f);DracoPicaro::pause(r,b,true);DracoPose::reset(r,b);++b.phase;b.mode=BossMode::Phase;b.phase_remaining=r.content->boss_bodies[b.definition-1].phase_time;e.guard=1;r.state.encounter_protected=true;godot::Dictionary event;event["boss"]="draco";event["id"]=r.state.enemy_handles.entity_id(b.actor);event["phase"]=b.phase;event["reason"]="hp_threshold";FrameBuilder::append(r,"boss_phase",event);update(r,b);}
    else if (b.phase==3 && e.hp<=0) {for (uint32_t row=0;row<r.state.bosses.techniques.size();++row) if (same_handle(r.state.bosses.techniques[row].actor,b.actor)) TechniqueRunner::cancel(r,r.state.bosses.handles.at(row));DracoPicaro::pause(r,b,true);DracoPose::reset(r,b);b.mode=BossMode::Final;e.guard=1;e.vel={};r.state.encounter_protected=true;for (auto &f:r.state.bosses.flows) if (same_handle(f.actor,b.actor)) {FlowRunner::cancel(r,f);f.suspended=true;} // 決着は後続の専用Runnerへ渡し、通常撃破を確定しない。
    }
}
bool DracoBody::validate(const godot::RunState &s,const ContentBundle &c,const BossBodyState &b) {if (c.bosses[c.boss_bodies[b.definition-1].boss-1].kind!=4) return true;const auto it=std::find_if(c.draco_bodies.begin(),c.draco_bodies.end(),[&](const auto &p){return p.boss==c.boss_bodies[b.definition-1].boss;});if (it==c.draco_bodies.end() || b.participants.size()!=it->body_segments+1 || !std::isfinite(b.draco.width) || b.draco.width<=0 || !std::isfinite(b.draco.head_scale) || b.draco.head_scale<=0 || !std::isfinite(b.draco.depth) || b.draco.depth<0.1 || b.draco.depth>1 || !std::isfinite(b.draco.alpha) || b.draco.alpha<0 || b.draco.alpha>1) return false;for (const auto *v:{&b.draco.trail,&b.draco.pose,&b.draco.override_points}) for (auto p:*v) if (!p.is_finite()) return false;for (size_t j=1;j<b.participants.size();++j) {const auto &p=b.participants[j];if (p.id<=0 || (s.enemy_handles.contains(p.actor) && s.enemy_handles.entity_id(p.actor)!=p.id) || p.is_body || !same_handle(p.health_target,b.actor) || p.active!=(b.mode<BossMode::Defeated)) return false;if (p.active && (!s.enemy_handles.contains(p.actor) || s.enemies[p.actor.slot].dead || !same_handle(s.enemies[p.actor.slot].damage_target,b.actor))) return false;}return DracoPicaro::validate(s,c,b);}
void DracoBody::snapshot(const RunRuntime &r,const BossBodyState &b,godot::Dictionary &p) {const auto &d=b.draco;godot::PackedVector2Array points;const auto at=r.state.enemies[b.actor.slot].pos;for (auto v:d.pose) points.push_back(at+(v-at)*d.depth);p["body_points"]=points;p["body_width"]=d.width;p["head_scale"]=d.head_scale;p["perspective_scale"]=d.depth;p["alpha"]=d.alpha;godot::Array segments;for (size_t j=1;j<b.participants.size();++j) {const auto actor=b.participants[j].actor;if (!r.state.enemy_handles.contains(actor)) continue;const auto &e=r.state.enemies[actor.slot];godot::Dictionary q;q["id"]=e.id;q["position"]=e.pos;q["radius"]=e.radius;q["hp"]=e.hp;segments.push_back(q);}p["segments"]=segments;p["picaro"]=DracoPicaro::snapshot(r,b);p["picaro_attacking"]=d.picaro_attacking;}
}
